-- ============================================================
-- 饰品特效转附魔卷轴（由 outputs/饰品武器特效转附魔/generate.py 生成，请勿手改）
-- 范围：ItemLevel >= 200 的饰品（InventoryType=12），ProcTypeMask>0 或 spelltrigger=2
-- 共 78 条特效；附魔 ID 30000~30077；法术 ID 94500~94577；卷轴 entry 63200~63277
-- 本脚本可重复执行（先 DELETE 再 INSERT）
-- ============================================================

 
-- 2) 附魔卷轴 item_template（class=0 消耗品 / subclass=8 附魔）
DELETE FROM `item_template` WHERE `entry` BETWEEN 63200 AND 63299;

-- 3) 命中触发附魔的 proc 数据 spell_enchant_proc_data
DELETE FROM `spell_enchant_proc_data` WHERE `entry` BETWEEN 30000 AND 30099;

-- 4) 运行时映射表 mod_trinket_essence_map（道具「饰品特效提取器」60105 查表用，见 src/TrinketEssence.cpp）

CREATE TABLE IF NOT EXISTS `mod_trinket_essence_map` (
  `spell_id`         INT UNSIGNED NOT NULL COMMENT '饰品上的原特效法术 ID',
  `enchant_id`       INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'spellitemenchantment_dbc.ID',
  `enchant_spell_id` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '附魔法术 spell_dbc.ID',
  `scroll_item`      INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '附魔卷轴 item_template.entry',
  `name`             VARCHAR(100) NOT NULL DEFAULT '' COMMENT '显示名',
  `src_item`         INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '来源饰品 entry',
  `src_spell_name`   VARCHAR(100) NOT NULL DEFAULT '' COMMENT '原特效法术名',
  PRIMARY KEY (`spell_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='饰品特效提取器：特效法术 -> 附魔卷轴 对应表';
DELETE FROM `mod_trinket_essence_map`;
